<script setup lang="ts">import{ref,computed}from'vue';import type{VoiceMeme}from'../../core/models';const props=defineProps<{items:VoiceMeme[]}>();const emit=defineEmits<{edit:[m:VoiceMeme];remove:[id:string];share:[m:VoiceMeme];new:[]}>();const filter=ref('全部');const shown=computed(()=>filter.value==='全部'?props.items:props.items.filter(i=>i.emotion===filter.value));</script>
<template><section class="gallery"><div class="gallery-head"><div><span class="kicker">05 / YOUR COLLECTION</span><h2>作品集</h2></div><button type="button" @click="emit('new')">＋ 新作品</button></div><div class="filters"><button v-for="f in ['全部','暴躁老哥','温柔姐姐','阴阳怪气','元气满满']" :key="f" :class="{active:filter===f}" @click="filter=f">{{ f }}</button></div><div v-if="!shown.length" class="empty-work">还没有作品，录一句今天最想说的话吧。</div><article v-for="item in shown" :key="item.id" class="work-card"><div class="work-head" :style="{background:`linear-gradient(135deg,${item.coverConfig.palette[0]},${item.coverConfig.palette[1]})`}"><div class="work-head-row"><b>{{ item.emotion }}</b><span class="source-tag" :class="item.emotionSource==='auto'?'auto':'manual'" :data-source="item.emotionSource==='auto'?'auto':'manual'">{{ item.emotionSource==='auto'?`自动 ${Math.round(item.confidence*100)}%`:'人工选择' }}</span></div><span class="work-duration">▶ {{ item.duration.toFixed(1) }}s<template v-if="item.voiceSummary"> · 有效声 {{ item.voiceSummary.voicedDuration.toFixed(1) }}s</template></span></div><h3>{{ item.title }}</h3><p>{{ new Date(item.createdAt).toLocaleDateString() }}</p><footer><button @click="emit('edit',item)">编辑</button><button @click="emit('share',item)">分享</button><button @click="emit('remove',item.id)">删除</button></footer></article></section></template>
